const colors = { frost: "#f5f5f5", char: "#101011", ash: "#1f1e1e", stone: "#282727" };
const luminance = (hex) => {
  const channels = [1, 3, 5].map((start) => Number.parseInt(hex.slice(start, start + 2), 16) / 255).map((channel) => channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4);
  return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2];
};
const foreground = luminance(colors.frost);
for (const [name, hex] of Object.entries(colors)) {
  if (name === "frost") continue;
  const ratio = (foreground + 0.05) / (luminance(hex) + 0.05);
  console.log(`${name}: ${ratio.toFixed(2)}:1`);
  if (ratio < 4.5) process.exitCode = 1;
}
'

